DROP TABLE IF EXISTS "public"."role_roles";
-- Table Definition
CREATE TABLE "public"."role_roles" (
    "id" int8 NOT NULL,
    "idRole" uuid NOT NULL,
    "section" text,
    "president" text,
    "juge" text,
    "assesseur" text,
    "assesseur1" text,
    "assesseur2" text,
    "conseillers" text,
    "ministerePublic" text,
    "greffier" text,
    "typeAudience" text,
    "dateEnreg" date,
    "filePath" text,
    "procureurMilitaire" text,
    "subtituts" text,
    "created_at" timestamptz,
    "statut" text,
    "created_by_id" int8,
    "juridiction_id" int8,
    CONSTRAINT "role_roles_created_by_id_dc6ad58d_fk_account_account_id" FOREIGN KEY ("created_by_id") REFERENCES "public"."account_account"("id"),
    CONSTRAINT "role_roles_juridiction_id_8381d0f0_fk__base_juridictions_id" FOREIGN KEY ("juridiction_id") REFERENCES "public"."_base_juridictions"("id"),
    PRIMARY KEY ("id")
);


-- Indices
CREATE INDEX role_roles_created_by_id_dc6ad58d ON public.role_roles USING btree (created_by_id);
CREATE INDEX role_roles_juridiction_id_8381d0f0 ON public.role_roles USING btree (juridiction_id);

